const std = @import("std");

const Entry = struct { row: usize, col: usize, val: i32 };

pub fn main() !void {
    const entries = [_]Entry{
        Entry{ .row = 0, .col = 0, .val = 10 },
        Entry{ .row = 0, .col = 3, .val = 20 },
        Entry{ .row = 2, .col = 1, .val = 30 },
        Entry{ .row = 3, .col = 4, .val = 40 },
    };

    for (entries) |e| {
        std.debug.print("[{},{}] = {}\n", .{e.row, e.col, e.val});
    }
}
